var gia = await _pricing.TinhGiaAsync(req.Items, ct);          // \u0111\u1ed3ng b\u1ed9\n    var kho = await _inventory.KiemTraKhoAsync(req.Items, ct);     // \u0111\u1ed3ng b\u1ed9\n    var khach = await _customer.LayAsync(req.CustomerId, ct);      // \u0111\u1ed3ng b\u1ed9\n\n    var don = Order.Tao(khach.Id, req.Items, gia.Value);\n    _db.Orders.Add(don);\n    await _db.SaveChangesAsync(ct);\n    return Result.ThanhCong();\n}\n"})}),(0,c.jsx)(e.pre,{children:(0,c.jsx)(e.code,{className:"language-csharp",children:'// SAU \u2014 ch\u1ec9 gi\u1eef \u0111\u1ed3ng b\u1ed9 th\u1ee9 TH\u1eacT S\u1ef0 c\u1ea7n tr\u01b0\u1edbc khi t\u1ea1o \u0111\u01a1n\npublic async Task<Result> TaoDonHangAsync(TaoDonRequest req, CancellationToken ct)\n{\n    // Gi\xe1: PH\u1ea2I \u0111\u1ed3ng b\u1ed9 \u2014 kh\xf4ng t\u1ea1o \u0111\u01a1n m\xe0 kh\xf4ng bi\u1ebft gi\xe1\n    var gia = await _pricing.TinhGiaAsync(req.Items, ct);\n    if (!gia.ThanhCong) return Result.Loi(gia.Loi);\n\n    // Kh\xe1ch h\xe0ng: d\xf9ng SNAPSHOT nh\xe2n b\u1ea3n qua event\n    var khach = await _db.CustomerSnapshots.FirstOrDefaultAsync(c => c.Id == req.CustomerId, ct);\n    if (khach is null) return Result.Loi("Kh\xf4ng t\xecm th\u1ea5y kh\xe1ch h\xe0ng");\n\n    var don = Order.Tao(khach.Id, req.Items, gia.Value);\n    _db.Orders.Add(don);\n\n    // Tr\u1eeb kho: B\u1ea4T \u0110\u1ed2NG B\u1ed8 qua event, c\xf3 b\xf9 tr\u1eeb n\u1ebfu kh\xf4ng \u0111\u1ee7 h\xe0ng\n    _db.Outbox.Add(TinNhanOutbox.Tao(new DonHangDaTaoV1(don.Id.Value, req.Items)));\n\n    await _db.SaveChangesAsync(ct);\n    return Result.ThanhCong();\n}\n'})}),(0,c.jsx)(e.pre,{children:(0,c.jsx)(e.code,{className:"language-text",children:"Ph\u1ee5 thu\u1ed9c \u0111\u1ed3ng b\u1ed9: 4 -> 2 (Gateway, Order, Pricing)\nUptime: 99,20% -> 99,70%\nDowntime: 70 gi\u1edd -> 26 gi\u1edd/n\u0103m\n"})}),(0,c.jsx)(e.p,{children:(0,c.jsx)(e.strong,{children:"C\xe1ch 2 \u2014 ph\u01b0\u01a1ng \xe1n d\u1ef1 ph\xf2ng khi service ph\u1ee5 ch\u1ebft:"})})